function spawnBone(x,y,vx,vy,w=14,h=70,blue=false){bones.push({x,y,vx,vy,w,h,blue,angle:Math.atan2(vy,vx)})}
function updateAttack(){attackFrame++;if(held.arrowup||held.w)move(0,-1);if(held.arrowdown||held.s)move(0,1);if(held.arrowleft||held.a)move(-1,0);if(held.arrowright||held.d)move(1,0);if(invuln>0)invuln--;
const t=attackFrame, ax=arena.x,ay=arena.y,aw=arena.w,ah=arena.h;
if(pattern===0){ // bone walls sweep across in alternating lanes
 if(t%46===1){const side=(Math.floor(t/46)%2===0)?-1:1;const y=ay+28+Math.random()*(ah-56);spawnBone(side<0?ax-25:ax+aw+25,y,side<0?5.2:-5.2,0,20,76,false);spawnBone(side<0?ax-25:y,0,0,0)}
 // cleanup malformed sentinel and add occasional falling bone
 if(t%95===28)spawnBone(ax+35+Math.random()*(aw-70),ay-30,0,4.2,12,54,false);
}else if(pattern===1){ // falling bone rain with safe gaps
 if(t%28===1){const x=ax+24+Math.random()*(aw-48);spawnBone(x,ay-45,0,4.8,14,65,(Math.floor(t/28)%3===1))}
 if(t%80===1){const fromLeft=t%160===1;spawnBone(fromLeft?ax-20:ax+aw+20,ay+ah*.55,fromLeft?4.8:-4.8,0,18,80,false)}
}else{ // sweeping horizontal lines
 if(t%60===1){let y=ay+42+Math.random()*(ah-84),fromLeft=Math.floor(t/60)%2===0;spawnBone(fromLeft?ax-35:ax+aw+35,y,fromLeft?5.5:-5.5,0,18,90,t%120===1)}
 if(t%92===24){for(let i=0;i<5;i++){if(i===2)continue;spawnBone(ax+aw*.28+i*28,ay-18,0,4.5,12,62,false)}}
}
for(let i=bones.length-1;i>=0;i--){const b=bones[i];b.x+=b.vx;b.y+=b.vy;if(b.x<ax-100||b.x>ax+aw+100||b.y>ay+ah+100){bones.splice(i,1);continue}if(invuln===0&&Math.abs(b.x-soul.x)<b.w/2+8&&Math.abs(b.y-soul.y)<b.h/2+8){hp=Math.max(0,hp-1);setHP();invuln=43;flash=.7;if(hp<=0){state='lost';setDialogue('* your determination is fading…');showResult(false);updateControls()}}}
if(--attackTimer<=0){state='player';bones=[];setDialogue('* sans yawns. your turn.');updateControls()}}
let last=0;function loop(ts){const dt=Math.min(40,ts-last);last=ts;if(state==='attack')updateAttack();raf=requestAnimationFrame(loop)}
// Renderer and game simulation run separately for crisp, stable movement.
requestAnimationFrame(draw);requestAnimationFrame(loop);setHP();updateControls();
})();
</script></body></html>

