function draw(){ctx.clearRect(0,0,W,H);const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#11131c');g.addColorStop(1,'#08090e');box(0,0,W,H,g);for(let i=0;i<7;i++){ctx.strokeStyle=`rgba(136,139,160,${.06-i*.005})`;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(480+(i-3)*64,0);ctx.lineTo(480+(i-3)*130,215);ctx.stroke()}ctx.fillStyle='#747686';ctx.globalAlpha=.12;ctx.fillRect(0,205,W,2);ctx.globalAlpha=1;for(let i=0;i<36;i++){const x=(i*173+frame*.12)%960,y=(i*71)%198;ctx.fillStyle=i%3?'#747889':'#f0df9e';ctx.globalAlpha=.15+Math.sin(frame*.03+i)*.08;ctx.fillRect(x,y,2,2)}ctx.globalAlpha=1;drawSans(480,104);text('SANS',480,190,10,'#bfc1cb','center');if(state==='intro'){text('…',480,365,14,'#555','center')}else if(state==='player'||state==='attack'||state==='enemyDown'){if(state==='attack')drawArena();else drawDialogue()}else if(state==='won'||state==='lost')drawDialogue();if(flash>0){ctx.fillStyle=`rgba(255,255,255,${flash*.18})`;ctx.fillRect(0,0,W,H);flash*=.85}frame++;requestAnimationFrame(draw)}
function drawDialogue(){box(90,292,780,150,'#050608','#e9e9e9',3);ctx.fillStyle='#fff';ctx.font='16px "Press Start 2P", monospace';ctx.textAlign='left';ctx.textBaseline='top';wrapText(dialogue,124,326,710,30,2);if(state==='player')text('▼',830,414,13,'#fff','center')}
function wrapText(t,x,y,max,lineHeight,maxLines){ctx.font='16px "Press Start 2P", monospace';let words=t.split(' '),line='',lines=[];for(const word of words){const test=line+word+' ';if(ctx.measureText(test).width>max&&line){lines.push(line.trim());line=word+' '}else line=test}if(line)lines.push(line.trim());lines.slice(0,maxLines).forEach((l,i)=>{ctx.fillStyle='#fff';ctx.fillText(l,x,y+i*lineHeight)})}
function drawArena(){box(arena.x,arena.y,arena.w,arena.h,'#050609','#f4f4f4',4);ctx.save();ctx.beginPath();ctx.rect(arena.x+2,arena.y+2,arena.w-4,arena.h-4);ctx.clip();for(const b of bones){ctx.save();ctx.translate(b.x,b.y);ctx.rotate(b.angle||0);ctx.fillStyle=b.blue?'#63dcff':'#f5f4ec';ctx.shadowColor=b.blue?'#51dfff':'#fff';ctx.shadowBlur=b.blue?11:0;ctx.fillRect(-b.w/2,-b.h/2,b.w,b.h);if(b.h>b.w){ctx.fillRect(-b.w,-b.h/2-3,b.w*2,8);ctx.fillRect(-b.w,b.h/2-5,b.w*2,8)}else{ctx.fillRect(-b.w/2-4,-b.h,b.w+8,b.h*2);ctx.fillRect(-b.w/2-4,0,b.w+8,b.h*2)}ctx.restore()}if(state==='attack'){ctx.fillStyle='#ff303a';ctx.shadowColor='#ff3344';ctx.shadowBlur=10;ctx.beginPath();ctx.moveTo(soul.x,soul.y-10);ctx.lineTo(soul.x+10,soul.y);ctx.lineTo(soul.x,soul.y+10);ctx.lineTo(soul.x-10,soul.y);ctx.closePath();ctx.fill();ctx.shadowBlur=0}ctx.restore();text('DODGE!',480,458,10,'#777','center')}
function setHP(){hpbar.style.width=`${Math.max(0,hp)/20*100}%`;hpnum.textContent=`${hp} / 20`}
function setDialogue(s){dialogue=s}
function updateControls(){document.querySelectorAll('.action').forEach(b=>b.disabled=state!=='player'&&b.id!=='again');document.getElementById('touch').style.opacity=state==='attack'?'1':'.48';turnlabel.textContent=state==='attack'?'DODGE!':state==='player'?'YOUR TURN':state==='won'?'BATTLE WON':'SANS\' TURN'}
function begin(){if(state!=='intro')return;document.getElementById('intro').classList.add('hide');state='player';setDialogue('* sans blocks the way. he looks bored.');updateControls()}document.getElementById('start').onclick=begin;
function act(action){if(state!=='player')return;if(action==='FIGHT'){bossHp-=26;flash=1;if(bossHp<=0){bossHp=0;state='won';setDialogue('* sans falls to one knee. “heh. guess you win.”');showResult(true);updateControls();return}setDialogue('* You swing at Sans. He dodges with a lazy step.')}if(action==='ACT'){actCount++;const lines=['* You tell a joke. Sans lets out a tiny snort.','* You offer to share your lunch. Sans considers it.','* Sans says, “you’re really going for it, huh?”'];setDialogue(lines[Math.min(actCount-1,2)])}if(action==='ITEM'){if(foodCount<=0){setDialogue('* Your pockets are empty.');return}foodCount--;hp=Math.min(20,hp+8);setHP();setDialogue('* You ate a cinnamon star. HP restored.')}if(action==='MERCY'){if(actCount>=2){state='won';setDialogue('* Sans steps aside. “that’s enough. you can go.”');showResult(true);updateControls();return}else setDialogue('* Sans shrugs. “not quite done yet, kid.”')}turn++;startAttack();updateControls()}
document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action));
function startAttack(){state='attack';attackFrame=0;pattern=(turn-1)%3;bones=[];soul={x:arena.x+arena.w/2,y:arena.y+arena.h/2};invuln=0;attackTimer=pattern===2?570:480;setDialogue('* sans is getting serious.');updateControls()}
function move(dx,dy){if(state!=='attack')return;const speed=focus?2.1:4.4;soul.x=Math.max(arena.x+15,Math.min(arena.x+arena.w-15,soul.x+dx*speed));soul.y=Math.max(arena.y+15,Math.min(arena.y+arena.h-15,soul.y+dy*speed))}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();held[k]=true;if(k==='shift')focus=true;if(k==='enter'&&state==='intro')begin();if(k==='enter'&&state==='player')act('FIGHT')});window.addEventListener('keyup',e=>{held[e.key.toLowerCase()]=false;if(e.key==='Shift')focus=false});
function bindPad(){document.querySelectorAll('[data-dir]').forEach(b=>{const d=b.dataset.dir,keys={up:'arrowup',down:'arrowdown',left:'arrowleft',right:'arrowright'};b.addEventListener('pointerdown',e=>{e.preventDefault();held[keys[d]]=true;b.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>held[keys[d]]=false))})}bindPad();const fbtn=document.getElementById('focus');fbtn.addEventListener('pointerdown',e=>{e.preventDefault();focus=true});['pointerup','pointercancel','pointerleave'].forEach(ev=>fbtn.addEventListener(ev,()=>focus=false));
function showResult(win){document.getElementById('resulttitle').textContent=win?'SPARED':'GAME OVER';document.getElementById('resultcopy').textContent=win?'The corridor is quiet again. Somehow, Sans still looks pretty relaxed.':'The corridor fades to black. Take a breath and try again.';setTimeout(()=>document.getElementById('modal').classList.add('show'),650)}document.getElementById('again').onclick=()=>{document.getElementById('modal').classList.remove('show');state='intro';document.getElementById('intro').classList.remove('hide');hp=20;bossHp=100;turn=0;actCount=0;foodCount=1;bones=[];setHP();updateControls()};

function spawnBone(x,y,vx,vy,w=14,h=70,blue=false){bones.push({x,y,vx,vy,w,h,blue,angle:Math.atan2(vy,vx)})}
function updateAttack(){attackFrame++;if(held.arrowup||held.w)move(0,-1);if(held.arrowdown||held.s)move(0,1);if(held.arrowleft||held.a)move(-1,0);if(held.arrowright||held.d)move(1,0);if(invuln>0)invuln--;const t=attackFrame,ax=arena.x,ay=arena.y,aw=arena.w,ah=arena.h;
if(pattern===0){if(t%46===1){const side=Math.floor(t/46)%2===0?-1:1,y=ay+28+Math.random()*(ah-56);spawnBone(side<0?ax-25:ax+aw+25,y,side<0?5.2:-5.2,0,20,76,false)}if(t%95===28)spawnBone(ax+35+Math.random()*(aw-70),ay-30,0,4.2,12,54,false)}else if(pattern===1){if(t%28===1){const x=ax+24+Math.random()*(aw-48);spawnBone(x,ay-45,0,4.8,14,65,Math.floor(t/28)%3===1)}if(t%80===1){const fromLeft=t%160===1;spawnBone(fromLeft?ax-20:ax+aw+20,ay+ah*.55,fromLeft?4.8:-4.8,0,18,80,false)}}else{if(t%60===1){const y=ay+42+Math.random()*(ah-84),fromLeft=Math.floor(t/60)%2===0;spawnBone(fromLeft?ax-35:ax+aw+35,y,fromLeft?5.5:-5.5,0,18,90,t%120===1)}if(t%92===24){for(let i=0;i<5;i++){if(i===2)continue;spawnBone(ax+aw*.28+i*28,ay-18,0,4.5,12,62,false)}}}
for(let i=bones.length-1;i>=0;i--){const b=bones[i];b.x+=b.vx;b.y+=b.vy;if(b.x<ax-100||b.x>ax+aw+100||b.y>ay+ah+100){bones.splice(i,1);continue}if(invuln===0&&Math.abs(b.x-soul.x)<b.w/2+8&&Math.abs(b.y-soul.y)<b.h/2+8){hp=Math.max(0,hp-1);setHP();invuln=43;flash=.7;if(hp<=0){state='lost';setDialogue('* your determination is fading…');showResult(false);updateControls()}}}if(--attackTimer<=0){state='player';bones=[];setDialogue('* sans yawns. your turn.');updateControls()}}
let last=0;function loop(ts){last=ts;if(state==='attack')updateAttack();requestAnimationFrame(loop)}requestAnimationFrame(draw);requestAnimationFrame(loop);setHP();updateControls();
})();
</script></body></html>

