(()=>{
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),hpbar=document.getElementById('hpbar'),hpnum=document.getElementById('hpnum'),turnlabel=document.getElementById('turnlabel');let W=960,H=540,state='intro',hp=20,bossHp=100,turn=0,frame=0,attackFrame=0,pattern=0,invuln=0,focus=false,held={},soul={x:0,y:0},bones=[],dialogue='* sans is standing in your way.',attackTimer=0,actCount=0,foodCount=1,flash=0;const arena={x:205,y:220,w:550,h:220};
function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=r.width*d;canvas.height=r.height*d;ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0)}window.addEventListener('resize',resize);resize();function text(t,x,y,size=14,color='#fff',align='left'){ctx.font=`${size}px "Press Start 2P",monospace`;ctx.fillStyle=color;ctx.textAlign=align;ctx.textBaseline='middle';ctx.fillText(t,x,y)}function box(x,y,w,h,fill,stroke=null,lw=2){ctx.fillStyle=fill;ctx.fillRect(x,y,w,h);if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.strokeRect(x,y,w,h)}}
function drawSans(x,y){ctx.save();ctx.translate(x,y);ctx.fillStyle='#252832';ctx.beginPath();ctx.ellipse(0,42,58,31,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#171a20';ctx.fillRect(-52,54,104,57);ctx.fillStyle='#f0eee7';ctx.beginPath();ctx.ellipse(0,0,43,39,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#b9b8b2';ctx.fillRect(-38,24,76,8);ctx.fillRect(-28,31,56,5);ctx.fillStyle='#151820';ctx.beginPath();ctx.ellipse(-15,3,11,15,-.2,0,Math.PI*2);ctx.ellipse(16,3,11,15,.2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#4cecff';ctx.shadowColor='#36dfff';ctx.shadowBlur=15;ctx.fillRect(-19,0,8,4);ctx.shadowBlur=0;ctx.strokeStyle='#31333a';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-17,22);ctx.quadraticCurveTo(0,28,17,21);ctx.stroke();for(let i=-12;i<=12;i+=8){ctx.fillStyle='#cac9c1';ctx.fillRect(i,22,4,4)}ctx.fillStyle='#222630';ctx.beginPath();ctx.moveTo(-41,45);ctx.lineTo(-53,100);ctx.quadraticCurveTo(0,120,53,100);ctx.lineTo(41,45);ctx.closePath();ctx.fill();ctx.fillStyle='#f2f1e9';ctx.beginPath();ctx.moveTo(-15,43);ctx.lineTo(0,66);ctx.lineTo(14,43);ctx.lineTo(19,104);ctx.lineTo(-20,104);ctx.closePath();ctx.fill();ctx.fillStyle='#e64e58';ctx.fillRect(-48,94,96,7);ctx.fillStyle='#eff0ed';ctx.fillRect(-58,97,16,12);ctx.fillRect(42,97,16,12);ctx.restore()}
